CustomField.formula:
IF(
/*If Account is Country Parent, stores DMS_Owner__c value */
ISPICKVAL(IM_Hierarchy_Level__c, 'Country Parent'), DMS_Owner__c ,
IF(
/*If Account is Sales site, stores Country Parent Account's DMS_Owner__c by traversing one level up the hierarchy*/
AND(ISPICKVAL(IM_Hierarchy_Level__c, 'Sales (Site)'),NOT(ISBLANK(ParentId))), Parent.DMS_Owner__c,DMS_Owner__c))
